def compact2(sequence):
    """
    Bonus 1: This version accepts any iterable, not just a sequence.
    """
    if type(sequence) == list and len(sequence) == 0:
        return sequence
    first, *rest = sequence
    output = [first]
    for el in rest:
        if el != output[-1]:
            output.append(el)
    return output

